type VariantChoice={key:string;candidate:BuildCandidate;quote:FmicQuote};
function PartsCarousel({count,en,children}:{count:number;en:boolean;children:ReactNode}){
 const track=useRef<HTMLDivElement>(null);
 const [position,setPosition]=useState({first:1,last:Math.min(count,4),prev:false,next:count>4});
 useEffect(()=>{
  const el=track.current;if(!el)return;
  const update=()=>{
   const left=el.scrollLeft,right=left+el.clientWidth;
   const cards=Array.from(el.children) as HTMLElement[];
   const visible=cards.map((card,i)=>({i,start:card.offsetLeft,end:card.offsetLeft+card.offsetWidth})).filter(c=>c.end>left+2&&c.start<right-2);
   setPosition({first:visible.length?visible[0].i+1:0,last:visible.length?visible[visible.length-1].i+1:0,prev:left>2,next:right<el.scrollWidth-2});
  };
  update();el.addEventListener('scroll',update,{passive:true});
  const observer=new ResizeObserver(update);observer.observe(el);
  return()=>{el.removeEventListener('scroll',update);observer.disconnect()};
 },[count]);
 const move=(direction:number)=>{
  const el=track.current;if(!el)return;
  const cards=Array.from(el.children) as HTMLElement[];
  const step=cards.length>1?cards[1].offsetLeft-cards[0].offsetLeft:el.clientWidth;
  const page=Math.max(1,Math.floor((el.clientWidth+2)/Math.max(1,step)));
  el.scrollBy({left:direction*step*page,behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});
 };
 if(!count)return null;
 return <div className="rpm-parts-carousel"><div className="rpm-carousel-toolbar"><span>{en?'Products':'Produkty'} <b>{position.first}–{position.last} / {count}</b></span></div><div className="rpm-carousel-stage"><div className="rpm-picker-magazine-grid rpm-carousel-track" ref={track} role="region" aria-label={en?'Product alternatives':'Alternatywy produktów'} tabIndex={0}>{children}</div>{(position.prev||position.next)&&<div className="rpm-carousel-buttons"><button type="button" className="outline rpm-carousel-prev" aria-label={en?'Previous products':'Poprzednie produkty'} disabled={!position.prev} onClick={()=>move(-1)}><ChevronLeft size={22}/></button><button type="button" className="outline rpm-carousel-next" aria-label={en?'Next products':'Następne produkty'} disabled={!position.next} onClick={()=>move(1)}><ChevronRight size={22}/></button></div>}</div>{count>1&&<div className="rpm-carousel-hint"><span>{en?'Swipe or use arrows to browse':'Przesuwaj w bok lub użyj strzałek'}</span><small>{en?'Remaining':'Pozostało'}: {Math.max(0,count-position.last)}</small></div>}</div>
}

function MaterialVariants({options,picked,busy,en,onChoose,rationale}:{options:VariantChoice[];picked?:string;busy:boolean;en:boolean;onChoose:(key:string)=>void;rationale:(key:string)=>string}){
 const tr=(pl:string,english:string)=>en?english:pl;
 const initial=options.find(o=>o.key===picked)?.candidate.variant;
 const [diameter,setDiameter]=useState(initial?String(initial.diameterMm):'');
 const [color,setColor]=useState(initial?.color??'');
 const [length,setLength]=useState(initial?.lengthMm?String(initial.lengthMm):'');
 const sizes=[...new Set(options.map(o=>o.candidate.variant!.diameterMm))].sort((a,b)=>a-b);
 const sizeOptions=options.filter(o=>String(o.candidate.variant!.diameterMm)===diameter);
 const colors=[...new Set(sizeOptions.flatMap(o=>o.candidate.variant?.color?[o.candidate.variant.color]:[]))];
 const lengths=[...new Set(sizeOptions.flatMap(o=>o.candidate.variant?.lengthMm?[o.candidate.variant.lengthMm]:[]))].sort((a,b)=>a-b);
 const choices=sizeOptions.filter(o=>(!colors.length||o.candidate.variant?.color===color)&&(!lengths.length||String(o.candidate.variant?.lengthMm)===length)).sort((a,b)=>{const price=(q:FmicQuote)=>q.available&&Number.isFinite(q.unitPrice)&&q.unitPrice>0?q.unitPrice:Infinity;return price(a.quote)===price(b.quote)?0:price(a.quote)-price(b.quote)});
 const colorLabel=(value:string)=>({black:tr('Czarny','Black'),red:tr('Czerwony','Red'),blue:tr('Niebieski','Blue')} as Record<string,string>)[value]??value;
 const money=(n:number)=>n.toLocaleString(en?'en-GB':'pl-PL',{style:'currency',currency:'PLN'});
 return <div className="rpm-build-material-variants"><div className="rpm-build-variant-fields">
  <label>{tr('Średnica nominalna','Nominal diameter')}<select value={diameter} disabled={busy} onChange={e=>{setDiameter(e.target.value);setColor('');setLength('')}}><option value="">{tr('Wybierz średnicę','Choose diameter')}</option>{sizes.map(d=><option key={d} value={d}>{d} mm</option>)}</select></label>
  {colors.length>0&&<label>{tr('Kolor','Colour')}<select value={color} disabled={busy} onChange={e=>{setColor(e.target.value as typeof color)}}><option value="">{tr('Wybierz kolor','Choose colour')}</option>{colors.map(c=><option key={c} value={c}>{colorLabel(c)}</option>)}</select></label>}
  {lengths.length>0&&<label>{tr('Długość odcinka','Section length')}<select value={length} disabled={busy} onChange={e=>{setLength(e.target.value)}}><option value="">{tr('Wybierz długość','Choose length')}</option>{lengths.map(n=><option key={n} value={n}>{n} mm</option>)}</select></label>}
 </div>
 <small>{tr('Wybierz średnicę po sprawdzeniu króćców lub zewnętrznej średnicy chronionego przewodu. Kolory i rozmiary odpowiadają rzeczywistym SKU.','Confirm diameter against fittings or the protected line outer diameter. Colours and sizes correspond to actual SKUs.')}</small>
 <PartsCarousel key={diameter+':'+color+':'+length} count={choices.length} en={en}>{choices.map(({key,candidate,quote})=><div className="rpm-parts-option rpm-carousel-material" key={key}>{quote.image&&<img src={quote.image} alt={quote.name} loading="lazy"/>}<div><small>SKU: {quote.sku}</small><strong>{quote.name}</strong><p className="rpm-product-rationale"><b>{tr('Dlaczego ten wariant?','Why this variant?')}</b>{rationale(key)}</p><details className="rpm-build-product-details"><summary>{tr('Parametry i montaż','Specifications & fitment')}</summary><p>{candidate.note[en?1:0]}</p></details><strong>{quote.available&&Number.isFinite(quote.unitPrice)&&quote.unitPrice>0?money(quote.unitPrice)+' / '+(candidate.materialUnitMm?candidate.materialUnitMm/10+' cm':tr('szt.','pc')):tr('Niedostępny / do wyceny','Unavailable / quote required')}</strong></div><button type="button" className={picked===key?'primary':'outline'} disabled={busy||picked===key||!quote.available||!Number.isFinite(quote.unitPrice)||quote.unitPrice<=0} onClick={()=>onChoose(key)}>{picked===key?tr('Wybrano','Selected'):tr('Wybierz wariant','Select variant')}</button></div>)}</PartsCarousel>
 </div>;
}
