 async function addManifold(){
  if(lock.current||!manifoldProduct||!manifoldSpec||!configuredManifold?.line||conflicts.some(i=>i.slots.includes('manifold')))return;
  lock.current=true;setBusy(manifoldProduct.sku);setCartStatus('');setCartError('');
  try{
   const r=await fetch('/api/catalog',{cache:'no-store'});if(!r.ok)throw Error();
   const d=await r.json();if(!Array.isArray(d.products))throw Error();
   const fresh=(d.products as RpmOption[]).find(p=>p.id===manifoldProduct.id&&p.sku===manifoldProduct.sku&&p.name===manifoldProduct.name&&p.visible===true&&['available','order'].includes(p.stockStatus??''));
   const next=fresh?manifoldConfiguration(fresh,manifoldSpec,customChoices):null;
   if(!next?.line||next.line.key!==configuredManifold.line.key||next.line.unitPrice!==configuredManifold.line.unitPrice){setRpmProducts(d.products);throw Error()}
   const raw:unknown=JSON.parse(localStorage.getItem('rpm-cart')??'[]');if(!Array.isArray(raw))throw Error();
   const lines=(raw as CartLine[]).filter(l=>l&&(l.fmicSku||!isRetiredDemoProductId(l.productId)));
   const existing=lines.find(l=>l.key===next.line!.key);
   if((existing?.qty??0)>=50||(!existing&&lines.length>=30))throw Error();
   const line={...next.line,qty:(existing?.qty??0)+1};
   localStorage.setItem('rpm-cart',JSON.stringify(existing?lines.map(l=>l.key===line.key?line:l):[...lines,line]));
   window.dispatchEvent(new Event(CART_EVENT));setCartStatus(manifoldProduct.sku);
  }catch{setCartError(manifoldProduct.sku)}finally{lock.current=false;setBusy('')}
 }
 if(!slots.length)return null;
 const quoteForSlot=(slot:typeof slots[number])=>{const k=selectedPart(slot,selection);return k?matched.find(q=>q.sku===candidates[k].sku):undefined};
 const grouped=systems.map(g=>({...g,parts:slots.filter(s=>(g.ids as readonly string[]).includes(s.id))}));
