  if(printButton)printButton.addEventListener('click',async()=>{printButton.disabled=true;const logo=popup.document.querySelector<HTMLImageElement>('img.logo');try{if(logo)await logo.decode()}catch{}finally{printButton.disabled=false;popup.focus();popup.print()}});setOfferError('');
