 {!onlyAssigned&&workshopSlots.length>0&&<details key={current.id+':workshop'} className="rpm-build-fold"><summary><Wrench size={17}/><span>{tr('Zalecenia warsztatowe','Workshop advice')}</span><small>{workshopSlots.length}</small><ChevronDown size={16}/></summary><section className="rpm-build-workshop-advice">{workshopSlots.map(s=><div key={s.id}><strong>{s.label[en?1:0]}</strong><p>{s.planNote?.[en?1:0]}</p></div>)}</section></details>}
 {!onlyAssigned&&excludedSlots.length>0&&<details key={current.id+':excluded'} className="rpm-build-fold"><summary><Package size={17}/><span>{tr('Pominięte pozycje','Skipped items')}</span><small>{excludedSlots.length}</small><ChevronDown size={16}/></summary><div className="rpm-build-task-list">{excludedSlots.map(renderSlot)}</div></details>}
