 {(profile.internals==='stock'||profile.rods==='stock')&&<p role="status">{tr('Seryjne tłoki lub korbowody to preferencja, nie potwierdzony limit wytrzymałości. Nie usuwamy automatycznie zaleceń dotyczących wzmocnienia.','Stock pistons or rods are a preference, not a confirmed strength limit. Reinforcement recommendations are not automatically removed.')}</p>}
 {profile.rods==='m50b25nv'&&<p role="status">{tr('M50B25 NV: wymagana indywidualna weryfikacja geometrii korbowodu, tłoka i wału. Brak automatycznego potwierdzenia dopasowania.','M50B25 NV: individual verification of rod, piston and crank geometry required. Fitment is not automatically confirmed.')}</p>}
 {profile.fuel==='flex'&&<p>{tr('Dla Flex Fuel przyjmujemy orientacyjny model E85; rzeczywisty skład paliwa i ciśnienie wymagają sprawdzenia.','Flex Fuel uses an illustrative E85 model; verify actual blend and pressure.')}</p>}
 <p>{pilot?tr('Wstępny dobór katalogowy według przedziału mocy, paliwa, wariantu i zgodności silnika. Dopasowanie fizyczne i trwałość wymagają potwierdzenia.','Preliminary catalogue selection based on power band, fuel, tier and engine application. Physical fitment and durability require confirmation.'):tr('Charakterystyka silnika oraz wybór tłoków i korbowodów zapisane. Automatyczny dobór pod te wymagania jest w przygotowaniu.','Engine characteristics and piston/rod preferences recorded. Automatic selection based on these requirements is planned.')}</p>
